css:
@import url("https://fonts.googleapis.com/css2?family=Gabarito:wght@500;700;800&family=Nunito+Sans:opsz,wght@6..12,400;6..12,600;6..12,700&display=swap");
:root{--navy:#111A3A;--navy-2:#26305A;--mint:#BFF0D4;--pink:#FF8FB1;--butter:#FFE58A;--sky:#CFE3FF;--bg:#F6F7FB;--text:#1D2440;--muted:#5A6283;
--display:"Gabarito",system-ui,sans-serif;--body:"Nunito Sans",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1180px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);font-family:var(--body);font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-family:var(--display);margin:0;line-height:1.05;color:var(--navy);letter-spacing:-.02em}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--butter);padding:10px 14px;z-index:99}
:focus-visible{outline:3px solid var(--navy);outline-offset:3px;border-radius:6px}
.site-header{position:sticky;top:12px;z-index:40;margin:12px auto 0}
.nav{display:flex;align-items:center;justify-content:space-between;height:66px;background:#fff;border-radius:999px;padding:0 10px 0 24px;box-shadow:0 10px 30px -18px rgba(17,26,58,.4)}
.logo{display:flex;align-items:center;gap:9px;font-family:var(--display);font-weight:800;font-size:22px;text-decoration:none;color:var(--navy)}
.logo i{width:26px;height:26px;border-radius:9px;background:var(--navy);display:grid;place-items:center}.logo i::after{content:"";width:10px;height:10px;border-radius:50%;background:var(--mint)}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:600}.menu a:hover{text-decoration:underline;text-underline-offset:4px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:13px 24px;border-radius:999px;font-weight:700;text-decoration:none;font-size:16px;border:2px solid var(--navy);cursor:pointer;font-family:var(--body);transition:transform .15s}
.btn:hover{transform:translateY(-2px)}
.btn-navy{background:var(--navy);color:#fff}.btn-light{background:#fff;color:var(--navy)}.btn-mint{background:var(--mint);color:var(--navy)}
.burger{display:none;background:none;border:0;padding:10px;cursor:pointer}.burger span{display:block;width:22px;height:2px;background:var(--navy);margin:5px 0}

.hero{padding:70px 0 90px}
.hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:50px;align-items:center}
.tagline{display:inline-flex;gap:8px;align-items:center;background:var(--butter);border-radius:999px;padding:6px 14px;font-weight:700;font-size:14px;margin-bottom:24px}
.hero h1{font-size:clamp(46px,6.6vw,88px);font-weight:800}
.hero h1 .blob{background:var(--mint);border-radius:18px;padding:0 .12em}
.hero .lead{font-size:20px;color:var(--muted);max-width:42ch;margin:24px 0 32px}
.signup{display:flex;gap:10px;background:#fff;border-radius:999px;padding:7px;max-width:470px;box-shadow:0 14px 30px -20px rgba(17,26,58,.5)}
.signup input{flex:1;border:0;font:inherit;padding:0 16px;background:transparent;min-width:0;color:var(--text)}.signup input:focus{outline:none}
.small{font-size:14px;color:var(--muted);margin-top:14px}
.visual{position:relative;min-height:540px}
.phone{position:absolute;inset:0 10% 0 10%;border-radius:40px;overflow:hidden;background:var(--sky)}
.phone img{width:100%;height:100%;object-fit:cover}
.float{position:absolute;background:#fff;border-radius:20px;padding:16px 18px;box-shadow:0 20px 40px -20px rgba(17,26,58,.45);font-size:14px;font-weight:600}
.float b{font-family:var(--display);font-size:26px;display:block;color:var(--navy)}
.f1{left:0;top:18%}.f2{right:0;bottom:16%;background:var(--pink)}
.f1 small{color:#1c9a5b}

.logos{padding:10px 0 70px}.logos p{text-align:center;color:var(--muted);font-weight:600;margin-bottom:20px}
.logo-row{display:flex;justify-content:center;gap:48px;flex-wrap:wrap}
.logo-row span{font-family:var(--display);font-weight:800;font-size:22px;color:#A3A9C2}

section{padding:100px 0}
.center{text-align:center;max-width:720px;margin:0 auto 54px}
.center h2,.h2{font-size:clamp(36px,4.6vw,60px);font-weight:800}
.center p{color:var(--muted);font-size:19px;margin-top:16px}

.bento{display:grid;grid-template-columns:repeat(6,1fr);grid-auto-rows:minmax(220px,auto);gap:18px}
.tile{border-radius:28px;padding:32px;position:relative;overflow:hidden}
.tile h3{font-size:28px;margin-bottom:10px}.tile p{font-size:16px;margin:0;max-width:38ch}
.t1{grid-column:span 4;background:var(--navy);color:#d6dbf2}.t1 h3{color:#fff}
.t1 img{position:absolute;right:-30px;bottom:-30px;width:46%;border-radius:22px;transform:rotate(-6deg)}
.t2{grid-column:span 2;background:var(--mint)}.t3{grid-column:span 2;background:var(--butter)}
.t4{grid-column:span 2;background:var(--pink)}.t5{grid-column:span 2;background:var(--sky)}
.big{font-family:var(--display);font-weight:800;font-size:64px;line-height:1;color:var(--navy);margin-bottom:10px;display:block}

.how{background:#fff;border-radius:40px;margin:0 16px}
.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.step{text-align:left}
.step .n{width:54px;height:54px;border-radius:18px;background:var(--navy);color:var(--mint);display:grid;place-items:center;font-family:var(--display);font-weight:800;font-size:24px;margin-bottom:18px}
.step h3{font-size:24px;margin-bottom:8px}.step p{color:var(--muted);margin:0}
.how-img{margin-top:56px;border-radius:28px;overflow:hidden}.how-img img{width:100%;aspect-ratio:21/8;object-fit:cover}

.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.stat{background:#fff;border-radius:24px;padding:28px}
.stat b{font-family:var(--display);font-weight:800;font-size:48px;display:block;color:var(--navy);line-height:1}
.stat span{color:var(--muted);font-size:15px}
.backers{margin-top:40px;background:var(--navy);color:#cfd5f0;border-radius:28px;padding:34px;display:flex;justify-content:space-between;align-items:center;gap:30px;flex-wrap:wrap}
.backers h3{color:#fff;font-size:24px}
.backers .row{display:flex;gap:34px;flex-wrap:wrap}.backers .row span{font-family:var(--display);font-weight:700;font-size:20px;color:#fff;opacity:.85}

.reviews{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.review{background:#fff;border-radius:24px;padding:28px}
.review .stars{color:#F5A623;letter-spacing:2px}
.review p{margin:12px 0 18px}
.who{display:flex;align-items:center;gap:12px}.who img{width:46px;height:46px;border-radius:50%;object-fit:cover}.who b{display:block;font-size:15px}.who span{font-size:14px;color:var(--muted)}

.team{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.member{background:#fff;border-radius:24px;padding:14px 14px 20px}
.member img{border-radius:16px;aspect-ratio:1/1;object-fit:cover;width:100%}
.member h3{font-size:21px;margin:14px 6px 2px}.member p{margin:0 6px;color:var(--muted);font-size:15px}
.jobs{margin-top:28px;background:var(--mint);border-radius:28px;padding:30px 34px;display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}
.jobs h3{font-size:26px}.jobs p{margin:4px 0 0}

.faq{max-width:820px;margin:0 auto}
.faq details{background:#fff;border-radius:20px;padding:20px 24px;margin-bottom:12px}
.faq summary{list-style:none;cursor:pointer;font-family:var(--display);font-weight:700;font-size:20px;display:flex;justify-content:space-between;gap:16px}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";font-size:26px;line-height:1}.faq details[open] summary::after{content:"−"}
.faq details p{color:var(--muted);margin:10px 0 0}

.final{background:var(--navy);color:#cfd5f0;border-radius:40px;margin:0 16px 16px;text-align:center}
.final h2{color:#fff;font-size:clamp(38px,5vw,68px);font-weight:800;max-width:16ch;margin:0 auto}
.final p{font-size:19px;max-width:48ch;margin:20px auto 30px}
.final .signup{margin:0 auto}
footer{padding:40px 0 34px;color:var(--muted);font-size:15px}
.foot{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:center}
.foot ul{display:flex;gap:22px;list-style:none;padding:0;margin:0;flex-wrap:wrap}.foot a{text-decoration:none}.foot a:hover{color:var(--navy)}
@media (max-width:980px){.menu,.nav>.btn{display:none}.burger{display:block}
.menu.open{display:flex;flex-direction:column;position:absolute;top:76px;left:0;right:0;background:#fff;padding:22px;border-radius:24px;gap:14px;box-shadow:0 20px 40px -20px rgba(17,26,58,.4)}
.hero-grid{grid-template-columns:1fr}.visual{min-height:460px}
.bento{grid-template-columns:1fr 1fr}.t1{grid-column:span 2}.t2,.t3,.t4,.t5{grid-column:span 1}
.steps,.reviews{grid-template-columns:1fr}.stats,.team{grid-template-columns:1fr 1fr}}
@media (max-width:600px){body{font-size:16px}section{padding:70px 0}
.bento{grid-template-columns:1fr}.t1,.t2,.t3,.t4,.t5{grid-column:auto}.t1 img{position:relative;right:auto;bottom:auto;width:80%;margin:24px auto 0;transform:none}
.stats,.team{grid-template-columns:1fr}.signup{flex-direction:column;border-radius:22px}.signup input{padding:12px}
.float{display:none}.phone{inset:0}.how,.final{margin:0 8px;border-radius:28px}}
